    h,w=len(grid),len(grid[0]); seen=set(); objs=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        st=[(r,c)];seen.add((r,c));co=[]
        while st:
          y,x=st.pop();co.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]]==2 and q not in seen:
              seen.add(q);st.append(q)
        if len(co)==4: objs.append(co)
    out=[[0]*6 for _ in range(3)]
    for co in objs:
      rs=[r for r,c in co];cs=[c for r,c in co]
      if len(set(rs))==2:
        bar=max(set(rs),key=lambda z:sum(r==z for r,c in co))
        stem=min(set(rs),key=lambda z:sum(r==z for r,c in co))
        sc=next(c for r,c in co if r==stem); bc=sorted(c for r,c in co if r==bar)
        val=3 if stem<bar else 1; ori=0 if sc==bc[0] else 1
      else:
        bar=max(set(cs),key=lambda z:sum(c==z for r,c in co))
        stem=min(set(cs),key=lambda z:sum(c==z for r,c in co))
        sr=next(r for r,c in co if c==stem); br=sorted(r for r,c in co if c==bar)
        val=3 if stem<bar else 1; ori=2 if sr==br[0] else 3
      row=min(2,int((sum(rs)/len(rs))*3/h))
      base=0 if sum(cs)/len(cs)<w/2 else 3
      out[row][base+ori]=val
    return out

